"""Intentional contextual explanations; no UI, model, network, or user data dependencies."""
from dataclasses import dataclass


@dataclass(frozen=True)
class HelpTopic:
    title: str
    tooltip: str
    paragraphs: tuple[str, ...]


def topic(title,tooltip,*paragraphs):
    return HelpTopic(title,tooltip,paragraphs)


